 void wire(){List<View> focus=new ArrayList<>();collect(a.rows,focus);for(View v:focus)v.setOnKeyListener((view,key,event)->{int direction=key==KeyEvent.KEYCODE_DPAD_DOWN?View.FOCUS_DOWN:key==KeyEvent.KEYCODE_DPAD_UP?View.FOCUS_UP:key==KeyEvent.KEYCODE_DPAD_LEFT?View.FOCUS_LEFT:key==KeyEvent.KEYCODE_DPAD_RIGHT?View.FOCUS_RIGHT:0;if(direction==0)return false;View art=a.rows.findViewWithTag("selection:artwork");View next=direction==View.FOCUS_LEFT&&art!=null?art:view.focusSearch(direction);if(next!=null&&next!=view&&event.getAction()==KeyEvent.ACTION_DOWN)next.requestFocus();return true;});}
 void collect(View v,List<View> out){if(v.isFocusable()&&v instanceof Button)out.add(v);if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++)collect(g.getChildAt(i),out);}}
